package com.example.inventory.dao;
import com.example.inventory.models.Vendor;import java.sql.*;import java.util.*;
public class VendorDao{private final Connection c;public VendorDao(Connection c){this.c=c;}public void addVendor(Vendor v)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO vendors(name,contact_info) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,v.getName());p.setString(2,v.getContactInfo());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())v.setId(r.getInt(1));}}}public void updateVendor(Vendor v)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE vendors SET name=?,contact_info=? WHERE id=?")){p.setString(1,v.getName());p.setString(2,v.getContactInfo());p.setInt(3,v.getId());p.executeUpdate();}}public List<Vendor> getAllVendors()throws SQLException{List<Vendor>o=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,contact_info FROM vendors ORDER BY id")){while(r.next())o.add(new Vendor(r.getInt(1),r.getString(2),r.getString(3)));}return o;}public void deleteVendor(int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("DELETE FROM vendors WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}}